KG42.register("edges-1a16a4df5748bbc58c951d36",{"id":"S-46c99aadf4025e0f","source":"KG31-fc19e7c39ea9de54","type":"links","target":"COMP-bf4a00350a51bde7","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["19-two_stage_battery_sharing"],"assertions":[{"id":"19-two_stage_battery_sharing::v141-c-R005::E::v141-c-R005-E001","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","rule_ref":"19-two_stage_battery_sharing::v141-c-R005","record":{"edge_id":"v141-c-R005-E001","source":"coordination.local_operator","target":"pricing.local","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-e014","v141-b-g02-E10","v141-b-g04-E12"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R005-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG31-fc19e7c39ea9de54","target":"COMP-bf4a00350a51bde7","source_occurrence_id":"19-two_stage_battery_sharing::v141-c-R005::V::coordination.local_operator","target_occurrence_id":"19-two_stage_battery_sharing::v141-c-R005::V::pricing.local","source_unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","target_unit_id":"19-two_stage_battery_sharing::v141-a-M01::pricing.local","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Buying and selling prices within the P2P sharing community. | Community P2P buying and selling prices at time t. | Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. | Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. | Compensating component of the community's modified SDR pricing mechanism. | Ex-post pricing within the P2P sharing community.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"]},"active":true,"source_signature":"6b6511358819868aa6b06e08e7b88068d66ed2b39b8674ed8f236dbdd3c8b436","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community. Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","target_definition":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community. P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community. P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism. Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community. Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","constraints":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e014","v141-b-g02-E10","v141-b-g04-E12"]}],"evidence":[{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-b91cee592e-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"m DERs, because the pricing and billing are conducted 24 h after the ng actual electricity consumpti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-b91cee592e-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":null,"anchor_text":"psumer premises. The purposes of the control is to minimize the amount of electricity fed back to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit."},{"evidence_id":"v141-b-g04-E12","location":{"location_id":"src-b91cee592e-p14-c1r4__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"participation willingness, the lowest compensating prices were 4, 3.5, en 6, 8.5 and 7.5 pence, resp","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Buying and selling prices within the P2P sharing community. | Community P2P buying and selling prices at time t. | Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. | Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. | Compensating component of the community's modified SDR pricing mechanism. | Ex-post pricing within the P2P sharing community.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"]},"source_record":{"edge_id":"v141-c-R005-E001","source":"coordination.local_operator","target":"pricing.local","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-e014","v141-b-g02-E10","v141-b-g04-E12"]},"paper_scope_note":"Electricity bill settlement directly depends on the post-metering price; the revenue improvement is a conditional statement and sensitivity case in the paper, not a general proposition independently verified in this work."}}],"assertion_ids":["19-two_stage_battery_sharing::v141-c-R005::E::v141-c-R005-E001"]});
